    row.update(printed_title=row['title'],product='Reflections',language='English',finish='Foil',uniqueness='Unique',copyright_year=1999,rarity=m['rarity'],article=src['article'],source_photo=src['local_file'],source_url=src['source_url'],source_sha256=src['sha256'],source_gallery=src['candidate']['source_html'],registry_key=src['candidate']['registry_key'],inspection='Full physical foil read on batch7 sheets 1–5; title, lore, text, stats and symbols transcribed independently',status='manually inspected and independently transcribed',gemp_mapping='unverified: omit playable ID')
    row['field_status']={k:'printed' for k in ['printed_title','type','subtype','model','destiny','power','deploy','forfeit','icons','lore','game_text','uniqueness','copyright_year']+[k for k in ['armor','maneuver','hyperspeed','landspeed','printed_label'] if k in row]};row['field_status']['rarity']='catalogued: Complete Card List v4.0'
